INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Fehlerbehebung > Software-Fehler
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Software-Fehler immer durch Hardware-Austausch behoben werden?', 2, '[{"text": "Nein", "correct": true, "because": "Software-Fehler sind nicht hardwareabhängig"}, {"text": "Ja", "correct": false, "because": "Austausch löst Softwareprobleme nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Software-Fehler immer durch Neuinstallation der Software behoben werden?', 2, '[{"text": "Nein", "correct": true, "because": "Updates oder Konfigurationsänderungen können reichen"}, {"text": "Ja", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Software-Fehler die Funktion der Hardware beeinträchtigen?', 2, '[{"text": "Ja", "correct": true, "because": "Fehlerhafte Treiber können Hardware stören"}, {"text": "Nein", "correct": false, "because": "Einfluss möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Fehlerbehebung von Software-Fehlern unabhängig von Diagnosewerkzeugen möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Werkzeuge wie Logs helfen bei der Analyse"}, {"text": "Ja", "correct": false, "because": "Diagnose oft erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Software-Fehler immer durch Benutzerfehler verursacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Programmierfehler oder Updates können Ursachen sein"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich benutzerbedingt"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Fehlerbehebung von Software-Fehlern am wichtigsten?', 3, '[{"text": "Fehleranalyse", "correct": true, "because": "Identifiziert Ursache"}, {"text": "Hardware-Austausch", "correct": false, "because": "Nicht primär"}, {"text": "Neustart", "correct": false, "because": "Nur temporäre Lösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug wird häufig zur Diagnose von Software-Fehlern verwendet?', 2, '[{"text": "Ereignisanzeige", "correct": true, "because": "Zeigt System- und Softwareereignisse"}, {"text": "Multimeter", "correct": false, "because": "Für Hardware"}, {"text": "Schraubendreher", "correct": false, "because": "Physische Reparatur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symptom deutet auf einen Software-Fehler hin?', 2, '[{"text": "Programmabsturz", "correct": true, "because": "Typisches Zeichen für Softwareprobleme"}, {"text": "Ungewöhnliche Geräusche", "correct": false, "because": "Hardwareproblem"}, {"text": "Kein Bildschirmlicht", "correct": false, "because": "Hardwaredefekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ursache ist bei Software-Fehlern am häufigsten?', 3, '[{"text": "Fehlerhafte Treiber", "correct": true, "because": "Häufige Schnittstellenprobleme"}, {"text": "Physischer Defekt", "correct": false, "because": "Hardwarebezogen"}, {"text": "Stromausfall", "correct": false, "because": "Externer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme hilft oft bei Software-Fehlern?', 2, '[{"text": "Update installieren", "correct": true, "because": "Behebt bekannte Fehler"}, {"text": "Kabel austauschen", "correct": false, "because": "Hardwarelösung"}, {"text": "Netzteil wechseln", "correct": false, "because": "Nicht softwarebezogen"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Fehlerbehebung von Software-Fehlern typisch?', 4, '[{"text": "Fehlerprotokolle prüfen", "correct": true, "because": "Liefert Hinweise"}, {"text": "Software aktualisieren", "correct": true, "because": "Behebt Bugs"}, {"text": "System neu starten", "correct": true, "because": "Löst temporäre Probleme"}, {"text": "Hardware austauschen", "correct": false, "because": "Nicht primär softwarebezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Symptome deuten auf Software-Fehler hin?', 3, '[{"text": "Programmabsturz", "correct": true, "because": "Softwareproblem"}, {"text": "Fehlermeldungen", "correct": true, "because": "Direkter Hinweis"}, {"text": "Langsame Reaktion", "correct": true, "because": "Softwarefehler möglich"}, {"text": "Überhitzung", "correct": false, "because": "Hardwareproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werkzeuge helfen bei der Fehlerbehebung von Software-Fehlern?', 3, '[{"text": "Ereignisanzeige", "correct": true, "because": "Zeigt Fehlerdetails"}, {"text": "Task-Manager", "correct": true, "because": "Überwacht Prozesse"}, {"text": "Diagnoseprogramme", "correct": true, "because": "Analysiert System"}, {"text": "Schraubendreher", "correct": false, "because": "Für Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ursachen können Software-Fehler haben?', 4, '[{"text": "Programmierfehler", "correct": true, "because": "Bugs in Code"}, {"text": "Inkompatible Treiber", "correct": true, "because": "Stören Kommunikation"}, {"text": "Konfigurationsfehler", "correct": true, "because": "Falsche Einstellungen"}, {"text": "Physischer Defekt", "correct": false, "because": "Hardwareproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen können Software-Fehler beheben?', 3, '[{"text": "Software aktualisieren", "correct": true, "because": "Behebt bekannte Fehler"}, {"text": "Treiber neu installieren", "correct": true, "because": "Korrigiert Treiberprobleme"}, {"text": "System zurücksetzen", "correct": true, "because": "Stellt Standardzustand her"}, {"text": "Kabel überprüfen", "correct": false, "because": "Hardwarelösung"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Programmabsturz deutet auf einen Software-Fehler hin. b) Software-Fehler können nur durch Neuinstallation behoben werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Absturz ja, Neuinstallation nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Fehlerhafte Treiber können Software-Fehler verursachen. b) Ein Neustart behebt keine Software-Probleme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Treiber ja, Neustart kann helfen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Ereignisanzeige hilft bei der Diagnose von Software-Fehlern. b) Software-Fehler betreffen nur das Betriebssystem.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ereignisanzeige ja, Fehler vielfältig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Software-Updates können Fehler beheben. b) Hardware-Fehler sind die Hauptursache für Software-Probleme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Updates ja, Hardware nicht primär"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Software-Fehler können durch Benutzerfehler entstehen. b) Diagnosewerkzeuge sind bei Software-Fehlern unnötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Benutzer ja, Werkzeuge hilfreich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

